diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..636495f 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,31 @@ export interface Record {
   warns: readonly string[];
 }

+const normalizeConstraint = (text: string): string => {
+  const lower = text.toLowerCase();
+  if (/stateful|infrastructure|operate|always-on|cache|operational/.test(lower)) {
+    return "no_new_operational_burden";
+  }
+  return text;
+};
+
+const deduplicateList = (items: readonly string[]): string[] => {
+  const seen = new Map<string, string>();
+  for (const item of items) {
+    const key = normalizeConstraint(item);
+    if (!seen.has(key)) {
+      seen.set(key, item);
+    }
+  }
+  return Array.from(seen.values());
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of deduplicateList(record.ruledOut)) lines.push(`- ruled out: ${entry}`);
+    for (const limit of deduplicateList(record.limits)) lines.push(`- limit: ${limit}`);
+    for (const warn of deduplicateList(record.warns)) lines.push(`- warn: ${warn}`);
   }
   return lines.join("\n");
 };
